cross join run;
DELETE FROM marts.customer_order_activity WHERE EXISTS (SELECT 1 FROM customer_order_activity__new WHERE customer_order_activity__new.customer_id = marts.customer_order_activity.customer_id AND customer_order_activity__new.snapshot_date = marts.customer_order_activity.snapshot_date);
